function podiumActivityBurst(card,gain){card._artBurst=(card._artBurst||0)+1;animatePodiumArt(card,Number(card.dataset.rank)+card._artBurst);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rank=Number(card.dataset.rank),rankFx=['gold','ice','ember'][rank-1]||'gold',level=Math.min(6,Math.max(2,Math.ceil(Math.log10(Math.max(1,gain)))+2));profileBubbles(card,{level,lastActivityKind:rank===1?'gift':'like'}, {effect:rankFx,duration:2200,variant:rank});card.classList.add('podium-energized');clearTimeout(card._energyTimer);card._energyTimer=setTimeout(()=>card.classList.remove('podium-energized'),1800);}
function animateProfilePoints(node,from,to,suffix,owner,showGain=true,duration=750,formatter=null){if(!node)return;const format=value=>formatter?formatter(value):String(value);if(node._pointRAF){cancelAnimationFrame(node._pointRAF);const current=Number.isFinite(node._counterValue)?node._counterValue:Number.parseInt(node.textContent);if(Number.isFinite(current))from=current;}node.dataset.target=String(to);node._counterValue=from;if(from===to||matchMedia('(prefers-reduced-motion: reduce)').matches){node._counterValue=to;node.textContent=format(to)+suffix;return;}node.textContent=format(from)+suffix;const start=performance.now();const draw=t=>{if(!node.isConnected)return;const p=Math.min(1,(t-start)/duration),v=Math.round(from+(to-from)*(1-(1-p)**3));node._counterValue=v;node.textContent=format(v)+suffix;if(p<1)node._pointRAF=requestAnimationFrame(draw);else{node.textContent=format(to)+suffix;node._pointRAF=null;}};node._pointRAF=requestAnimationFrame(draw);node.animate([{color:'#fff4b0'},{color:'#ffffff',offset:.4},{color:'#fff4b0'}],{duration:700});if(to>from&&showGain){const gain=el('span','profile-point-gain','+'+(to-from));owner.append(gain);const a=gain.animate([{transform:'translateY(8px)',opacity:0},{transform:'translateY(-4px)',opacity:1,offset:.2},{transform:'translateY(-28px)',opacity:0}],{duration:1200,easing:'ease-out'});a.finished.then(()=>gain.remove(),()=>gain.remove());}}
function profileTime(ms){const n=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function profileBubbles(target,p,plan){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const existing=[...document.querySelectorAll('.profile-spark')];for(const old of existing.slice(0,Math.max(0,existing.length-180)))old.remove();const level=p.level||0,gift=p.lastActivityKind==='gift',count=Math.min(100,plan.particleBudget??(6+level*3+(gift?8:0))),fx=gift?'gold':plan.effect,colour=gift?'#ffda70':'var(--profile-accent,#8de7ff)';target.dataset.fx=fx;const overlay=el('span','profile-fx-overlay fx-'+fx);overlay.style.setProperty('--fx-colour',colour);target.append(overlay);overlay.innerHTML='<i class="fx-streak"></i><i class="fx-streak second"></i><i class="fx-mist"></i><i class="fx-bolt"></i>';setTimeout(()=>{overlay.remove();if(target.dataset.fx===fx)delete target.dataset.fx;},plan.duration);for(let i=0;i<count;i++){const b=el('i','profile-spark particle-'+fx,gift?'✦':fx==='crown'?'♛':fx==='ice'||fx==='prism'?'◆':i%3===0?'✦':'');target.append(b);b.style.color=colour;b.style.left=(target.classList.contains('profile-podium-card')?(i%2?92:4):(8+(i*37)%84))+'%';const seed=(i+1)*2.399963,distance=24+level*4+i%5*8,dx=target.classList.contains('profile-podium-card')?(i%2?1:-1)*(15+level*3+i%5*3):Math.cos(seed)*distance,dy=Math.sin(seed)*distance-20,spin=(i%2?1:-1)*(90+i*17);const frames=fx==='wave'||fx==='aurora'||fx==='ribbon'?[{transform:'translate(0,15px) scale(.1)',opacity:0},{transform:`translate(${dx}px,-20px) scale(1)`,opacity:1,offset:.3},{transform:`translate(${-dx}px,${-70-i%4*10}px) scale(.2) rotate(${spin}deg)`,opacity:0}]:fx==='electric'?[{transform:'translate(0,10px)',opacity:0},{transform:`translate(${dx}px,${dy}px)`,opacity:1,offset:.15},{transform:`translate(${-dx*.5}px,${dy-10}px)`,opacity:.7,offset:.45},{transform:`translate(${dx*.8}px,${dy-40}px) scale(.1)`,opacity:0}]:[{transform:'translate(0,15px) scale(.1)',opacity:0},{transform:`translate(${dx*.4}px,${dy*.4}px) scale(1.2)`,opacity:1,offset:.2},{transform:`translate(${dx}px,${dy-50}px) rotate(${spin}deg) scale(.1)`,opacity:0}];const a=b.animate(frames,{duration:1400+i%5*260,delay:i%6*80,fill:'forwards',easing:'cubic-bezier(.15,.5,.3,1)'});a.finished.then(()=>b.remove(),()=>b.remove());}}

